// Throwaway mobile UI prototype: selected clinical layout with risk history.
// All account, device, measurement, and risk state is in memory. No clinical algorithm.
const paths={arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',chevron:'m9 5 7 7-7 7',home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',history:'M3 12a9 9 0 1 0 3-6M3 3v5h5m4-1v5l3 2',user:'M20 21v-2a7 7 0 0 0-14 0v2m10-14a4 4 0 1 1-8 0 4 4 0 0 1 8 0',scale:'M6 3h12a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3Zm2 5a6 6 0 0 1 8 0l-4 5Zm4 2 2-4',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Zm-4 9 3 3 5-6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',activity:'M2 12h5l3-8 4 16 3-8h5',bluetooth:'m7 7 10 10-5 4V3l5 4L7 17',signal:'M4 18v2m5-7v7m5-12v12m5-17v17',check:'m5 12 4 4L19 6',leaf:'M20 3C8 2 3 7 5 14s14 10 15-11ZM5 20 16 8',ruler:'m3 17 14-14 4 4L7 21Zm6-6 3 3m1-7 3 3',lock:'M5 10h14v11H5Zm3 0V7a4 4 0 0 1 8 0v3',phone:'M7 2h10v20H7Zm4 16h2',close:'m6 6 12 12M6 18 18 6',wifi:'M3 8a14 14 0 0 1 18 0M6 12a9 9 0 0 1 12 0m-9 4a4 4 0 0 1 6 0m-3 3h.01',battery:'M2 7h17v10H2Zm20 3v4M5 10h11v4H5Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-9-5v5l3 2',edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14Z',info:'M12 11v6m0-10v.01m9 5a9 9 0 1 1-18 0 9 9 0 0 1 18 0',logout:'M9 4H4v16h5m-1-8h13m-5-5 5 5-5 5'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.activity}"/></svg>`;
const logo=()=>`<div class="brand"><svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><path d="M9 32a16 16 0 1 1 23-2" stroke="#8fc1d1" stroke-width="2"/><path d="M13 29a11 11 0 1 1 15-1" stroke="#4e96ae" stroke-width="2"/><path d="m14 22 5 5 9-14" stroke="#4e96ae" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><circle cx="32" cy="11" r="3" fill="#f5d574"/></svg><span>Dia<span>Scale</span></span></div>`;
const scaleArt=()=>`<svg viewBox="0 0 180 180" fill="none" aria-hidden="true"><circle cx="112" cy="64" r="48" stroke="#f2d273" stroke-width="6"/><rect x="27" y="49" width="121" height="113" rx="25" fill="#fcfefa" stroke="#8dbac9" stroke-width="2" transform="rotate(-9 87 106)"/><rect x="64" y="64" width="48" height="28" rx="7" fill="#e0eef1" transform="rotate(-9 88 78)"/><path d="m81 78 5 4 8-11" stroke="#4e96ae" stroke-width="2" stroke-linecap="round"/><rect x="42" y="112" width="32" height="32" rx="12" fill="#dbe9ec" transform="rotate(-9 58 128)"/><rect x="103" y="102" width="32" height="32" rx="12" fill="#dbe9ec" transform="rotate(-9 119 118)"/><circle cx="33" cy="45" r="5" fill="#a9ccd7"/><path d="M153 139v12m-6-6h12" stroke="#7db2c3" stroke-width="2" stroke-linecap="round"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);
const riskStyle='porcelain';
const variant='A';

const sampleProfile={name:'Nadia Putri',birth:'1992-05-14',height:'162',waist:'84',meds:'Tidak',glucose:'Tidak',family:'Ya'};
const state={screen:params.get('screen')||'welcome',mode:'signup',phone:'',profile:{name:'',birth:'',height:'',waist:'',meds:'',glucose:'',family:''},history:[],selected:null,device:'DS-001',scenario:'multiple',failure:'none',period:'month',stage:0,editing:false,toast:''};
const demoHistory=()=>[0,1,2,3].map((n)=>({id:100-n,date:new Date(2026,9,20-n*7,8,30),weight:[64.2,64.6,65.1,65.4][n],bmi:[24.5,24.6,24.8,24.9][n],risk:'Sedang',score:[54,58,61,64][n],device:'DS-001',profile:{...sampleProfile}}));
let timers=[];
function clearTimers(){timers.forEach(clearTimeout);timers=[]}
function later(fn,ms){timers.push(setTimeout(fn,ms))}
function go(screen){clearTimers();state.screen=screen;render();document.querySelector('.screen')?.scrollTo(0,0)}
function toast(message){state.toast=message;render();later(()=>{state.toast='';render()},2400)}
const dateText=d=>new Date(d).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});
const initials=()=>state.profile.name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('')||'DS';
const button=(text,action,style='',ico='arrow')=>`<button type="button" class="btn ${style}" data-action="${action}">${text}${ico?icon(ico):''}</button>`;
const back=(action='home')=>`<button class="back" data-action="${action}" aria-label="Kembali">${icon('back')}</button>`;
const header=()=>`<header class="app-header">${logo()}<button class="avatar" data-action="profile" aria-label="Buka profil">${esc(initials())}</button></header>`;
const top=(title,action='home',right='')=>`<div class="page-top">${back(action)}<span>${right}</span></div><h1>${title}</h1>`;
const field=(label,name,type='text',unit='',value=state.profile[name],extra='')=>`<label class="field"><span class="field-label">${label}</span><div class="input-wrap"><input name="${name}" type="${type}" value="${esc(value)}" ${unit?'class="with-unit"':''} required ${extra}>${unit?`<span class="unit">${unit}</span>`:''}</div></label>`;
function nav(){return `<nav class="bottom-nav" aria-label="Navigasi utama">${[['home','Beranda'],['history','Riwayat'],['profile','Profil']].map(([key,label])=>`<button class="nav-item ${state.screen===key?'active':''}" data-action="${key}" ${state.screen===key?'aria-current="page"':''}>${icon(key==='profile'?'user':key)}${label}</button>`).join('')}</nav>`}
function metrics(record){return `<div class="metrics"><div><div class="metric-label">${icon('scale')}Berat badan</div><div class="metric-value">${record.weight.toFixed(1).replace('.',',')}<small>kg</small></div></div><div><div class="metric-label">${icon('ruler')}Indeks massa tubuh</div><div class="metric-value">${record.bmi.toFixed(1).replace('.',',')}<small>kg/m²</small></div></div></div>`}
// Each variant combines the latest risk and measurement action in one primary section.
const homeDetail=r=>r?`<button class="text-btn" data-action="detail" data-id="${r.id}">Lihat hasil lengkap ${icon('chevron')}</button>`:'';
const homeStamp=r=>r?`Terakhir diukur · ${dateText(r.date)}`:'Belum ada pengukuran';
function riskTrend(){
  const records=state.history.slice(0,6).reverse();
  const heading=`<div class="section-head"><h2>Riwayat risiko</h2><button class="text-btn" data-action="history">Lihat riwayat</button></div>`;
  if(!records.length)return `${heading}<section class="risk-trend-card"><div class="trend-empty"><div class="icon-box">${icon('activity')}</div><h3>Mulai pantau risiko Anda</h3><p>Skor risiko setiap pengukuran akan tercatat di sini setelah Anda menimbang.</p></div></section>`;
  const firstNumber=state.history.length-records.length+1;
  const points=records.map((r,i)=>({x:30+(records.length===1?130:i*270/(records.length-1)),y:125-r.score,record:r,number:firstNumber+i}));
  return `${heading}<section class="risk-trend-card" aria-label="Riwayat skor risiko diabetes tipe 2"><svg class="risk-chart" viewBox="0 0 320 152" role="img" aria-label="Skor risiko berdasarkan urutan pengukuran: ${points.map(p=>`pengukuran ${p.number}, skor ${p.record.score}`).join('; ')}"><defs><linearGradient id="risk-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a9cfdb" stop-opacity=".45"/><stop offset="1" stop-color="#edf5f7" stop-opacity=".1"/></linearGradient></defs>${[0,50,100].map(score=>`<path d="M30 ${125-score}H307" stroke="#e7eff1" stroke-dasharray="3 4"/><text x="0" y="${129-score}">${score}</text>`).join('')}${points.length>1?`<path d="M${points.map(p=>`${p.x},${p.y}`).join(' L')} L${points.at(-1).x},125 L${points[0].x},125Z" fill="url(#risk-fill)"/><path d="M${points.map(p=>`${p.x},${p.y}`).join(' L')}" fill="none" stroke="#4e96ae" stroke-width="2.5" stroke-linejoin="round"/>`:''}${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4.5" fill="white" stroke="#4e96ae" stroke-width="2"><title>${dateText(p.record.date)} · Skor ${p.record.score}</title></circle><text class="risk-point-value" x="${p.x}" y="${p.y-12}" text-anchor="middle">${p.record.score}</text><text x="${p.x}" y="145" text-anchor="middle">${String(new Date(p.record.date).getDate()).padStart(2,'0')}/${String(new Date(p.record.date).getMonth()+1).padStart(2,'0')}</text>`).join('')}</svg>${records.length===1?'<p class="trend-note">Lakukan pengukuran berikutnya untuk melihat perubahan skor risiko.</p>':''}</section>`;
}
function VariantA(r){return `<section class="combined-card clinical-card" aria-label="Risiko dan pengukuran"><p class="risk-title">Risiko diabetes tipe 2</p>${r?`<div class="combined-risk"><h2>Risiko ${r.risk.toLowerCase()}</h2><span class="badge">${r.score} / 100</span></div><div class="risk-track"></div><div class="track-labels"><span>Rendah</span><span>Sedang</span><span>Tinggi</span></div>${metrics(r)}`:`<h2 class="first-title">Kenali risiko Anda,<br>mulai dari sini.</h2><p class="combined-description">Lakukan pengukuran pertama untuk mengetahui risiko diabetes tipe 2 Anda.</p>`}<div class="combined-action"><p class="measurement-stamp">${r?icon('clock'):icon('scale')}${homeStamp(r)}</p>${button(r?'Ukur kembali':'Ukur sekarang','scan')}${homeDetail(r)}</div></section>${riskTrend()}`}
function home(){return `${header()}<p class="greeting">${new Date().getHours()<11?'Selamat pagi':'Halo'}, ${esc(state.profile.name.split(' ')[0]||'Anda')}</p><h1>Kenali risiko.<br>Pantau perubahannya.</h1>${VariantA(state.history[0])}`}
function welcome(){return `<header class="app-header">${logo()}<span class="eyebrow" style="font-size:8px">Kenali lebih awal</span></header><div class="auth-art">${scaleArt()}</div><div class="eyebrow" style="margin:30px 0 12px">Satu langkah untuk diri Anda</div><h1>Pahami risiko,<br>mulai dari data<br>tubuh Anda.</h1><p class="subheading" style="margin:17px 0 29px">Kenali dan pantau risiko diabetes tipe 2, dari rumah maupun rumah sakit.</p>${button('Buat akun','signup')}<div style="height:11px"></div>${button('Sudah punya akun? Masuk','login','secondary','')}<div class="privacy">${icon('shield')}Langkah sederhana. Kesehatan lebih terpantau.</div>`}
function auth(){let signup=state.mode==='signup';return `${top(signup?'Mulai langkah<br>sehat Anda.':'Selamat<br>datang kembali.','welcome')}<p class="subheading">${signup?'Daftar':'Masuk'} dengan nomor HP Anda.</p><div class="auth-art">${icon('phone')}</div><form id="phone-form"><label class="field"><span class="field-label">Nomor HP</span><div class="input-wrap"><span class="prefix">+62</span><input class="phone-input" name="phone" type="tel" inputmode="tel" autocomplete="tel-national" placeholder="812 3456 7890" value="${esc(state.phone)}" pattern="[0-9 +()-]{8,18}" required></div></label><p class="small muted" style="margin-bottom:24px">Nomor HP digunakan untuk profil di perangkat ini.</p><button class="btn" type="submit">Lanjutkan ${icon('arrow')}</button></form><p class="auth-footer">${signup?'Sudah punya akun?':'Belum punya akun?'} <button class="text-btn" data-action="${signup?'login':'signup'}">${signup?'Masuk':'Daftar'}</button></p><div class="privacy">${icon('lock')}Informasi kesehatan Anda bersifat pribadi.</div>`}
function personal(){return `${top(state.editing?'Perbarui<br>data diri.':'Kenali Anda<br>lebih dekat.',state.editing?'profile':'auth',state.editing?'':'Langkah 1 dari 2')}<div class="steps" style="margin-top:22px"><span class="done"></span><span></span></div><p class="subheading">Data ini membantu melengkapi penilaian risiko Anda.</p><form id="personal-form">${field('Nama lengkap','name','text','','', 'autocomplete="name"').replace('value=""',`value="${esc(state.profile.name)}"`)}${field('Tanggal lahir','birth','date','',state.profile.birth,`max="${new Date().toISOString().slice(0,10)}"`)}<div class="form-grid">${field('Tinggi badan','height','number','cm',state.profile.height,'min="80" max="250" step="0.1" inputmode="decimal"')}${field('Lingkar pinggang','waist','number','cm',state.profile.waist,'min="30" max="250" step="0.1" inputmode="decimal"')}</div><details class="help"><summary style="cursor:pointer;font-weight:600">Cara mengukur lingkar pinggang</summary><p style="margin-top:8px">Berdiri rileks. Lingkarkan pita ukur di pertengahan antara rusuk terbawah dan bagian atas tulang panggul. Pastikan pita mendatar, tidak menekan kulit, lalu baca saat selesai mengembuskan napas biasa.</p></details><button type="submit" class="btn">Lanjutkan ${icon('arrow')}</button></form>`}
const questions=[['meds','Apakah Anda pernah atau sedang menggunakan obat antihipertensi?'],['glucose','Apakah Anda pernah memiliki hasil glukosa darah tinggi?'],['family','Apakah ada anggota keluarga yang memiliki diabetes?']];
function health(){return `${top(state.editing?'Perbarui riwayat<br>kesehatan.':'Sedikit tentang<br>kesehatan Anda.','personal',state.editing?'':'Langkah 2 dari 2')}<div class="steps" style="margin-top:22px"><span class="done"></span><span class="done"></span></div><p class="subheading">Jawab sesuai kondisi yang Anda ketahui.</p><form id="health-form">${questions.map(([name,q])=>`<div class="question"><fieldset><legend>${q}</legend><div class="choices">${['Ya','Tidak','Tidak tahu'].map(v=>`<label class="choice"><input type="radio" name="${name}" value="${v}" required ${state.profile[name]===v?'checked':''}><span>${v}</span></label>`).join('')}</div></fieldset></div>`).join('')}<div class="form-actions"><button class="btn" type="submit">${state.editing?'Simpan perubahan':'Selesaikan pendaftaran'} ${icon('check')}</button></div></form>`}
function scan(){return `${top('Hubungkan<br>DiaScale.')}<p class="subheading">Pastikan Bluetooth aktif dan Anda berada di dekat timbangan.</p><div class="scan-center"><div class="scan-orbit">${icon('bluetooth')}</div><h2>Mencari timbangan…</h2><p>Menemukan perangkat DiaScale di sekitar Anda.</p></div>`}
function devices(){return `${top('Pilih timbangan.')}<p class="subheading">Cocokkan nomor unit di aplikasi dengan nomor pada timbangan yang akan digunakan.</p><div class="section-head"><h2>Perangkat di sekitar</h2><span class="small muted">3 ditemukan</span></div>${['DS-001','DS-008','DS-012'].map((id,i)=>`<button class="device" data-action="connect" data-device="${id}"><div class="icon-box">${icon('scale')}</div><div class="device-info"><h3>DiaScale ${id}</h3><p>Unit ${id.slice(3)} · ${i===0?'Sinyal kuat':i===1?'Sinyal sedang':'Sinyal lemah'}</p></div>${icon('signal')}${icon('chevron')}</button>`).join('')}<div class="notice">Gunakan timbangan yang kosong dan siap digunakan.</div><div class="form-actions">${button('Cari ulang','scan','secondary','bluetooth')}</div>`}
function measuring(){let titles=['Menghubungkan…','Timbangan siap.','Sedang mengukur…','Menyiapkan hasil…'];let desc=['Menghubungkan HP dengan timbangan pilihan Anda.','Silakan lepas alas kaki, lalu naik ke timbangan.','Berdiri tegak dan tetap diam hingga pengukuran selesai.','Pengukuran selesai. Tunggu sebentar untuk melihat hasil Anda.'];return `${top('Pengukuran.')}<p class="subheading">DiaScale ${esc(state.device)} <span class="badge blue" style="margin-left:7px">${state.stage?'Terhubung':'Menghubungkan'}</span></p><div class="scan-center" aria-live="polite"><div class="scan-orbit">${state.stage===2?icon('activity'):icon('scale')}</div><h2>${titles[state.stage]}</h2><p>${desc[state.stage]}</p></div>${state.stage===2||state.stage===3?'<div class="progress"><span></span></div>':''}${['Hubungkan perangkat','Naik ke timbangan','Ukur & tetap diam','Terima hasil'].map((x,i)=>`<div class="measure-stage ${i===state.stage?'active':i<state.stage?'complete':''}"><span class="stage-number">${i<state.stage?icon('check'):i+1}</span>${x}</div>`).join('')}<button class="text-btn" data-action="home" style="width:100%;margin-top:17px">Batalkan pengukuran</button>`}
function errorScreen(){let missing=state.screen==='notfound',connection=state.screen==='connection-error';return `${top(missing?'Belum menemukan<br>timbangan.':connection?'Koneksi terputus.':'Pengukuran<br>belum berhasil.')}<div class="scan-center"><div class="scan-orbit">${icon(missing?'bluetooth':connection?'wifi':'scale')}</div><h2>${missing?'Coba dekatkan HP Anda':connection?'Mari hubungkan kembali':'Coba sekali lagi'}</h2><p>${missing?'Pastikan timbangan menyala, Bluetooth aktif, dan unit berada di dekat Anda.':connection?'Pastikan HP tetap berada di dekat timbangan dan perangkat masih menyala.':'Turun dari timbangan, tunggu hingga siap, lalu naik kembali dan berdiri diam.'}</p></div>${button(missing?'Cari ulang':'Coba lagi',missing?'scan':'retry')}<div style="height:12px"></div>${button('Kembali ke beranda','home','secondary','')}`}
function result(){const r=state.selected||state.history[0];if(!r)return `<div class="empty"><h2>Belum ada hasil</h2>${button('Mulai pengukuran','scan')}</div>`;return `${top('Rincian risiko.',state.returnTo||'home',dateText(r.date))}<p class="subheading">DiaScale ${esc(r.device)} · ${new Date(r.date).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}</p><section class="score-panel"><div class="eyebrow">Risiko diabetes melitus tipe 2</div><div class="score-main"><div><p class="small muted">Kategori risiko Anda</p><h2>${r.risk}</h2><span class="badge">Perlu perhatian</span></div><div class="score-circle" style="--risk-score:${r.score}%"><span>${r.score}<small>dari 100</small></span></div></div><div class="risk-track" style="--risk-position:${r.score}%"></div><div class="track-labels"><span>Rendah</span><span>Sedang</span><span>Tinggi</span></div></section><section class="risk-contributions risk-style-${riskStyle}" aria-labelledby="contributions-title"><h2 id="contributions-title">Rincian kontribusi risiko</h2><table class="contribution-table"><thead><tr><th scope="col">Faktor</th><th scope="col">Hasil</th><th scope="col">Poin</th></tr></thead><tbody>${[['Lemak viseral','12 level',30],['Persentase lemak','28,4%',1],['BMI',`${r.bmi.toFixed(1).replace('.',',')} kg/m²`,20],['Massa otot','24,1 kg',0],['Obat antihipertensi',r.profile.meds,r.profile.meds==='Ya'?5:0]].map(([label,value,points])=>`<tr><th scope="row">${label}</th><td>${esc(value)}</td><td><span class="point-chip ${points>0?'point-risk':'point-neutral'}">${points>0?'+':''}${points}</span></td></tr>`).join('')}</tbody></table></section><div class="section-head"><h2>Data pengukuran pendukung</h2></div><div class="result-card measurement-summary">${metrics(r)}</div><div class="section-head"><h2>Data kesehatan saat pengukuran</h2></div><div class="factor"><span>Lingkar pinggang</span><span>${esc(r.profile.waist)} cm</span></div><div class="factor"><span>Riwayat diabetes keluarga</span><span>${esc(r.profile.family)}</span></div><div class="factor"><span>Riwayat glukosa darah tinggi</span><span>${esc(r.profile.glucose)}</span></div><div class="factor"><span>Penggunaan obat antihipertensi</span><span>${esc(r.profile.meds)}</span></div><div class="form-actions">${button('Lihat riwayat risiko','history','secondary','history')}</div><div class="privacy">${icon('check')}Hasil tersimpan di riwayat Anda.</div>`}
function chart(records){let chronological=[...records].reverse(),scores=chronological.map(r=>r.score),low=0,high=100,range=100;let pts=chronological.map((r,i)=>[30+(chronological.length===1?125:i*260/(chronological.length-1)),105-(r.score-low)/range*80]);return `<svg class="chart" viewBox="0 0 320 140" role="img" aria-label="Grafik skor risiko diabetes tipe 2 dari ${scores[0]} ke ${scores.at(-1)} dari 100"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#c2dfe8" stop-opacity=".65"/><stop offset="1" stop-color="#f8fbfc" stop-opacity=".2"/></linearGradient></defs>${[0,1,2].map(n=>`<path d="M30 ${25+n*40}H305" stroke="#edf1f2" stroke-dasharray="3 4"/><text x="0" y="${29+n*40}">${(high-n*range/2).toFixed(0)}</text>`).join('')}<path d="M${pts.map(p=>p.join(',')).join(' L')} L${pts.at(-1)[0]},113 L${pts[0][0]},113Z" fill="url(#chart-fill)"/><path d="M${pts.map(p=>p.join(',')).join(' L')}" stroke="#4e96ae" stroke-width="2.5" fill="none"/>${pts.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="white" stroke="#4e96ae" stroke-width="2"/><text x="${x}" y="135" text-anchor="middle">${String(new Date(chronological[i].date).getDate()).padStart(2,'0')}/${String(new Date(chronological[i].date).getMonth()+1).padStart(2,'0')}</text>`).join('')}</svg>`}
function history(){const records=state.history.filter(r=>state.period==='all'||new Date(r.date)>=new Date(new Date().getTime()-(state.period==='week'?7:31)*86400000));return `${header()}<h1>Riwayat risiko.</h1><p class="subheading">Pantau perubahan risiko diabetes tipe 2 dari setiap pengukuran.</p><div class="filter-tabs" aria-label="Rentang waktu">${[['week','7 hari'],['month','30 hari'],['all','Semua']].map(([v,t])=>`<button data-action="period" data-period="${v}" class="${state.period===v?'active':''}" aria-pressed="${state.period===v}">${t}</button>`).join('')}</div>${records.length?`<section class="chart-card"><div class="heading-row"><h2 style="font-size:13px">Perubahan skor risiko</h2><span class="small muted">0–100</span></div><div class="history-summary"><strong>${records[0].score}</strong><span>/ 100 · skor risiko terbaru</span></div>${chart(records)}</section><div class="section-head"><h2>Semua hasil penilaian risiko</h2><span class="small muted">${records.length} hasil</span></div>${records.map(r=>`<button class="history-item" data-action="detail" data-id="${r.id}"><div class="history-info"><h3>${dateText(r.date)}</h3><p>Risiko ${r.risk.toLowerCase()}</p></div><div class="history-value"><b>${r.score} <small>/ 100</small></b><p>Skor risiko</p></div>${icon('chevron')}</button>`).join('')}`:`<div class="empty"><div class="icon-box">${icon('history')}</div><h2>${state.history.length?'Belum ada hasil di periode ini':'Perjalanan Anda dimulai di sini'}</h2><p>${state.history.length?'Pilih rentang waktu yang lebih panjang untuk melihat pengukuran sebelumnya.':'Lakukan pengukuran pertama untuk mulai memantau risiko diabetes tipe 2 Anda.'}</p>${button('Ukur sekarang','scan')}</div>`}`}
function profile(){return `${header()}<div class="heading-row"><h1>Profil Anda.</h1><button class="text-btn" data-action="edit">Edit profil</button></div><div class="profile-head"><div class="avatar">${esc(initials())}</div><h2>${esc(state.profile.name||'Pengguna DiaScale')}</h2><p class="small muted">+62 ${esc(state.phone||'812 3456 7890')}</p></div><div class="section-head"><h2>Data diri</h2></div>${[['Tanggal lahir',state.profile.birth?dateText(state.profile.birth):'—'],['Tinggi badan',`${state.profile.height} cm`],['Lingkar pinggang',`${state.profile.waist} cm`]].map(([a,b])=>`<div class="profile-row"><span>${a}</span><span>${esc(b)}</span></div>`).join('')}<div class="section-head"><h2>Riwayat kesehatan</h2></div>${[['Obat antihipertensi',state.profile.meds],['Glukosa darah tinggi',state.profile.glucose],['Diabetes dalam keluarga',state.profile.family]].map(([a,b])=>`<div class="profile-row"><span>${a}</span><span>${esc(b)}</span></div>`).join('')}<div class="form-actions">${button('Keluar dari akun','logout','secondary','logout')}</div>`}
const screens={welcome,auth,personal,health,home,scan,devices,measuring,result,history,profile,notfound:errorScreen,'connection-error':errorScreen,'measure-error':errorScreen};
function pagePicker(){const pages=[['welcome','Halaman awal'],['auth','Masuk / daftar'],['personal','Data diri'],['health','Riwayat kesehatan'],['home','Beranda'],['devices','Pilih timbangan'],['measuring','Pengukuran'],['result','Rincian risiko'],['history','Riwayat risiko'],['profile','Profil'],['notfound','Timbangan tidak ditemukan'],['connection-error','Koneksi terputus'],['measure-error','Pengukuran gagal']];return `<div class="page-picker"><label for="page-jump">Halaman</label><select id="page-jump">${pages.map(([key,label])=>`<option value="${key}" ${state.screen===key?'selected':''}>${label}</option>`).join('')}</select></div>`}
function render(){let s=screens[state.screen]?state.screen:'welcome';const authenticated=['home','history','profile','result'].includes(s);document.getElementById('app').innerHTML=`<div class="shell"><aside class="identity">${logo()}<div class="intro"><div class="eyebrow">Kenali tubuh. Pahami risiko.</div><h1>Langkah kecil.<br><em>Makna besar</em><br>untuk kesehatan.</h1><div class="intro-rule"></div><p>Kenali risiko diabetes tipe 2 melalui data tubuh Anda. Mulai kebiasaan baik, satu pengukuran setiap waktu.</p></div><div class="intro-bottom"><span>${icon('shield')}Personal untuk Anda</span><span>${icon('activity')}Terpantau dari waktu ke waktu</span></div></aside><section class="phone variant-${variant.toLowerCase()}" data-screen="${s}" aria-label="Aplikasi DiaScale"><div class="statusbar"><span>9:41</span><span class="status-icons">${icon('signal')}${icon('wifi')}${icon('battery')}</span></div><main class="screen ${authenticated?'':'auth-view'}"><div class="content">${screens[s]()}</div></main>${authenticated?nav():''}${state.toast?`<div class="toast" role="status">${esc(state.toast)}</div>`:''}<div class="home-indicator"></div></section></div>${pagePicker()}`;console.debug('DiaScale prototype state',{...state,variant});}
function startScan(){go('scan');later(()=>{if(state.scenario==='none')go('notfound');else if(state.scenario==='single')connect('DS-001');else go('devices')},1800)}
function connect(device){state.device=device;state.stage=0;go('measuring');later(()=>{if(state.failure==='connection'){state.failure='none';go('connection-error');return}state.stage=1;render();later(()=>{state.stage=2;render();later(()=>{if(state.failure==='measurement'){state.failure='none';go('measure-error');return}state.stage=3;render();later(finishMeasurement,1800)},3200)},3200)},1500)}
function finishMeasurement(){const weight=64.2,bmi=+(weight/((Number(state.profile.height)||162)/100)**2).toFixed(1);let record={id:Date.now(),date:new Date(),weight,bmi,risk:'Sedang',score:54,device:state.device,profile:{...state.profile}};state.history.unshift(record);state.selected=record;state.returnTo='home';go('result')}
function demo(){state.profile={...sampleProfile};state.phone='812 3456 7890';state.history=demoHistory();state.editing=false;go('home')}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let action=b.dataset.action;switch(action){case'signup':case'login':state.mode=action;go('auth');break;case'scan':startScan();break;case'connect':connect(b.dataset.device);break;case'retry':connect(state.device);break;case'detail':state.selected=state.history.find(r=>r.id===Number(b.dataset.id));state.returnTo=state.screen;go('result');break;case'period':state.period=b.dataset.period;render();break;case'edit':state.editing=true;go('personal');break;case'logout':state.selected=null;go('welcome');break;default:if(screens[action])go(action)}});
document.addEventListener('submit',e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));switch(e.target.id){case'phone-form':state.phone=data.phone.replace(/^0/,'');if(state.mode==='login'){if(!state.profile.name){state.profile={...sampleProfile};state.history=demoHistory()}go('home')}else go('personal');break;case'personal-form':Object.assign(state.profile,data);go('health');break;case'health-form':Object.assign(state.profile,data);let editing=state.editing;state.editing=false;go(editing?'profile':'home');if(editing)toast('Profil berhasil diperbarui.');break}});
document.addEventListener('change',e=>{
  if(e.target.id!=='page-jump')return;
  const screen=e.target.value;
  if(!state.profile.name){state.profile={...sampleProfile};state.phone='812 3456 7890'}
  if(['result','history'].includes(screen)&&!state.history.length)state.history=demoHistory();
  if(screen==='result'){state.selected=state.history[0];state.returnTo='home'}
  if(screen==='measuring'){connect(state.device);return}
  go(screen);
});
if(params.get('demo')==='1'){state.profile={...sampleProfile};state.phone='812 3456 7890';state.history=demoHistory();state.screen=params.get('screen')==='result'?'result':'home'}
document.body.classList.add('no-tools');
render();

// Preserve the 390 × 844 layout while fitting it within a non-scrolling stage.
function fitCanvas(){
  const mobile=window.innerWidth<=480;
  const reserved=mobile?60:24;
  const scale=Math.min(1,(window.innerHeight-reserved)/844,(window.innerWidth-(mobile?0:48))/390);
  document.documentElement.style.setProperty('--phone-scale',Math.max(.1,scale));
}
window.addEventListener('resize',fitCanvas);
fitCanvas();
